import { HierarchyRectangularNode } from '@visx/hierarchy/lib/types';
import { isUndefined } from 'lodash-es';
import React, { useEffect, useMemo } from 'react';

import { BarCanvas } from '../../core/components/canvas/components/BarCanvas.js';
import type { LegendItem } from '../../core/components/legend/categorical/types/legend.js';
import { DEFAULT_FILL_OPACITY } from '../../core/constants.js';
import { getOpacity } from '../../core/functions/getOpacity.js';
import { DEFAULT_ENTRY_NAME } from '../defaults.js';
import { useSetState } from '../store/selectors.js';
import { InternalTreeMapClusterNode } from '../types/internal.js';
import { TreeMapState } from '../types/state.js';

export const TreemapCanvas = ({
  treemap,
  width,
  height,
  highlightedItems,
}: {
  treemap: HierarchyRectangularNode<InternalTreeMapClusterNode>;
  highlightedItems: LegendItem[] | undefined;
  width: number;
  height: number;
}): JSX.Element => {
  const x = (
    entry: HierarchyRectangularNode<InternalTreeMapClusterNode>,
  ): number => entry.x0;
  const y = (
    entry: HierarchyRectangularNode<InternalTreeMapClusterNode>,
  ): number => entry.y0;
  const entryWidth = (
    entry: HierarchyRectangularNode<InternalTreeMapClusterNode>,
  ): number => entry.x1 - entry.x0;
  const entryHeight = (
    entry: HierarchyRectangularNode<InternalTreeMapClusterNode>,
  ): number => entry.y1 - entry.y0;
  const zeroAxis = (): number => 0;
  const opacity = (
    entry: HierarchyRectangularNode<InternalTreeMapClusterNode>,
  ): number => {
    if (!highlightedItems || highlightedItems.length === 0) {
      return DEFAULT_FILL_OPACITY;
    }
    const name =
      entry.parent?.data.name || entry.data.name || DEFAULT_ENTRY_NAME;
    const isCurrentHighlighted = !!highlightedItems?.find(
      (node) => node.name === name,
    );
    return getOpacity(isCurrentHighlighted);
  };

  const getColor = (
    entry: HierarchyRectangularNode<InternalTreeMapClusterNode>,
  ): string => {
    const isRootNode = !isUndefined(entry.data.color);
    const color = isRootNode ? entry.data.color : entry.parent?.data.color;
    return color?.Default ?? 'transparent';
  };

  const visibleNodes = useMemo(
    () =>
      treemap
        .descendants()
        .reverse()
        .filter((entry) => entry.depth > 1),
    [treemap],
  );
  const setState = useSetState();
  useEffect(() => {
    setState((prev: TreeMapState) => ({
      ...prev,
      visibleNodes,
    }));
  }, [visibleNodes, setState]);

  return (
    <BarCanvas
      x={x}
      y={y}
      width={entryWidth}
      height={entryHeight}
      data={visibleNodes}
      canvasWidth={width}
      canvasHeight={height}
      zeroAxis={zeroAxis}
      color={getColor}
      opacity={opacity}
    />
  );
};
